#!/usr/bin/env bash\n\n# Mock rationale: we replace the real Docker CLI with a mock function so the test can run offline without Docker installed.\n# The mock will simulate successful build and run, returning a predictable output for a known input file.\n\n# Save original PATH and prepend a temporary directory containing the mock.\nTMPDIR=$(mktemp -d)\nexport PATH="$TMPDIR:$PATH"\n\n# Create mock docker executable\ncat > "$TMPDIR/docker" <<'EOF'\n#!/usr/bin/env bash\n\n# Simple mock that handles 'docker build' and 'docker run' commands used in the test.\nif [ "$1" = "build" ]; then\n  echo "Mock docker build invoked"\n  exit 0\nelif [ "$1" = "run" ]; then\n  shift\n  # Capture arguments after 'run' (we ignore them for the mock)\n  echo "Mock docker run invoked with args: $@"\n  # Simulate the output of count.sh for the sample input "Hello world"\n  cat <<OUTPUT\n🧭 Apocalypse Wordcount Report 🧭\nLines: 1\nWords: 2\nBytes: 12\nOUTPUT\n  exit 0\nelse\n  echo "Unsupported docker command in mock: $@"\n  exit 1\nfi\nEOF\nchmod +x "$TMPDIR/docker"\n\n# Create a sample input file\nprintf "Hello world" > sample.txt\n\n# Run the mocked docker build (should succeed)\nif ! docker build -t nightly-docker-wordcount .; then\n  echo "Docker build mock failed"\n  exit 1\nfi\n\n# Run the mocked container against the sample file\nOUTPUT=$(docker run --rm -v "$(pwd)":/data nightly-docker-wordcount sample.txt)\n\n# Verify the output contains the expected counts\nif [[ "$OUTPUT" == *"Lines: 1"* ]] && [[ "$OUTPUT" == *"Words: 2"* ]] && [[ "$OUTPUT" == *"Bytes: 12"* ]]; then\n  echo "Test passed"\n  exit 0\nelse\n  echo "Test failed – unexpected output:"\n  echo "$OUTPUT"\n  exit 1\nfi
